INSERT INTO ai_knowledge_chunk (
    document_id, base_id, category_id, chunk_no, chunk_type, heading_path,
    content_text, keyword_text, region_scope, doc_type, topic_type, policy_name, policy_aliases, policy_no,
    chapter_title, section_title, scene_priority, searchable, content_length, sort_no, create_time
) VALUES

    (
        #{item.documentId}, #{item.baseId}, #{item.categoryId}, #{item.chunkNo}, #{item.chunkType}, #{item.headingPath},
        #{item.contentText}, #{item.keywordText}, #{item.regionScope}, #{item.docType}, #{item.topicType}, #{item.policyName}, #{item.policyAliases}, #{item.policyNo},
        #{item.chapterTitle}, #{item.sectionTitle}, #{item.scenePriority}, #{item.searchable}, #{item.contentLength}, #{item.sortNo}, #{item.createTime}
    )

mapper.select:
SELECT doc.id AS document_id, chunk.id AS chunk_id, doc.doc_title, doc.policy_region, chunk.heading_path, chunk.content_text AS snippet, chunk.keyword_text, chunk.region_scope, chunk.doc_type, chunk.topic_type, chunk.policy_name, chunk.policy_aliases, chunk.policy_no, chunk.chapter_title, chunk.section_title, chunk.scene_priority, chunk.searchable, chunk.chunk_no FROM ai_knowledge_chunk chunk INNER JOIN ai_knowledge_document doc ON doc.id = chunk.document_id WHERE doc.is_deleted = FALSE AND chunk.base_id = #{request.baseId}
AND chunk.searchable = #{request.searchable}
AND chunk.category_id = #{request.categoryId}
AND chunk.region_scope = #{request.regionScope}
AND chunk.doc_type = #{request.docType}
AND chunk.topic_type = #{request.topicType}
AND (chunk.scene_priority = #{request.scenePriority} OR chunk.scene_priority = 'GENERAL')
AND ( chunk.content_text LIKE CONCAT('%', #{request.keywords}, '%') OR doc.doc_title LIKE CONCAT('%', #{request.keywords}, '%') OR COALESCE(chunk.keyword_text, '') LIKE CONCAT('%', #{request.keywords}, '%') OR COALESCE(chunk.policy_name, '') LIKE CONCAT('%', #{request.keywords}, '%') OR COALESCE(chunk.policy_aliases, '') LIKE CONCAT('%', #{request.keywords}, '%') OR COALESCE(chunk.policy_no, '') LIKE CONCAT('%', #{request.keywords}, '%') OR COALESCE(chunk.chapter_title, '') LIKE CONCAT('%', #{request.keywords}, '%') OR COALESCE(chunk.section_title, '') LIKE CONCAT('%', #{request.keywords}, '%') )
AND doc.policy_region LIKE CONCAT('%', #{request.policyRegion}, '%')
AND (doc.effective_date IS NULL OR doc.effective_date <= CURRENT_DATE) AND (doc.expire_date IS NULL OR doc.expire_date >= CURRENT_DATE)
ORDER BY CASE
WHEN COALESCE(chunk.region_scope, '') = #{request.regionScope} THEN 0
WHEN COALESCE(chunk.policy_name, '') = #{request.keywords} THEN 1 WHEN COALESCE(chunk.policy_aliases, '') LIKE CONCAT('%', #{request.keywords}, '%') THEN 2 WHEN COALESCE(chunk.policy_no, '') LIKE CONCAT('%', #{request.keywords}, '%') THEN 3
WHEN COALESCE(chunk.topic_type, '') = #{request.questionType} THEN 4
WHEN COALESCE(chunk.doc_type, '') = 'topic' THEN 5 WHEN COALESCE(chunk.doc_type, '') = 'main' THEN 6 WHEN COALESCE(chunk.doc_type, '') = 'guide' THEN 9
WHEN COALESCE(chunk.heading_path, '') LIKE CONCAT('%', #{request.regionPriority}, '%') THEN 7 WHEN chunk.content_text LIKE CONCAT('%', #{request.regionPriority}, '%') THEN 7 WHEN doc.doc_title LIKE CONCAT('%', #{request.regionPriority}, '%') THEN 8 WHEN COALESCE(chunk.keyword_text, '') LIKE CONCAT('%', #{request.regionPriority}, '%') AND COALESCE(chunk.heading_path, '') NOT LIKE CONCAT('%', #{request.regionPriority}, '%') AND chunk.content_text NOT LIKE CONCAT('%', #{request.regionPriority}, '%') AND doc.doc_title NOT LIKE CONCAT('%', #{request.regionPriority}, '%') THEN 10
ELSE 11 END, doc.update_time DESC, chunk.sort_no ASC
ORDER BY CASE
WHEN COALESCE(chunk.region_scope, '') = #{request.regionScope} THEN 0
WHEN COALESCE(chunk.policy_name, '') = #{request.keywords} THEN 1 WHEN COALESCE(chunk.policy_aliases, '') LIKE CONCAT('%', #{request.keywords}, '%') THEN 2 WHEN COALESCE(chunk.policy_no, '') LIKE CONCAT('%', #{request.keywords}, '%') THEN 3
WHEN COALESCE(chunk.topic_type, '') = #{request.questionType} THEN 4
WHEN COALESCE(chunk.doc_type, '') = 'topic' THEN 5 WHEN COALESCE(chunk.doc_type, '') = 'main' THEN 6 WHEN COALESCE(chunk.doc_type, '') = 'guide' THEN 9 ELSE 10 END, doc.update_time DESC, chunk.sort_no ASC
LIMIT #{request.topN}
